package thaumcraft.verification;

import java.util.*;
import java.util.function.BiConsumer;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.phys.*;
import thaumcraft.entities.*;
import thaumcraft.items.*;
import thaumcraft.registry.*;

final class GolemBellVerification {
    private static ThaumicGolem worker(ServerLevel level,ServerPlayer player,BlockPos home,int upgrade){var body=new ItemStack(R3Equipment.GOLEM_BODIES.get(GolemMaterial.WOOD).get());CustomData.update(DataComponents.CUSTOM_DATA,body,t->{t.putInt("core",4);t.putBoolean("advanced",true);t.putByteArray("upgrades",new byte[]{(byte)upgrade});t.putString("deco","H");});var g=R3Entities.GOLEM.get().create(level);g.initialize(GolemMaterial.WOOD,player.getUUID(),home,Direction.UP,body);g.moveTo(home.getCenter());g.setNoAi(true);level.addFreshEntity(g);return g;}
    static void run(ServerLevel level,ServerPlayer player,BiConsumer<Boolean,String> c){
        var p=new BlockPos(650,184,10);var bell=new ItemStack(R3Equipment.GOLEM_BELL.get());player.setItemInHand(InteractionHand.MAIN_HAND,bell);player.setShiftKeyDown(false);
        GolemBellItem.changeMarkers(bell,player,p,Direction.UP);c.accept(GolemBellItem.markers(bell).size()==1,"unbound bell records a marker before selecting a golem");GolemBellItem.changeMarkers(bell,player,p,Direction.UP);c.accept(GolemBellItem.markers(bell).isEmpty(),"unbound bell toggles an existing marker off");
        player.setShiftKeyDown(true);GolemBellItem.changeMarkers(bell,player,p,Direction.EAST);c.accept(GolemBellItem.markers(bell).size()==1,"original Shift click still creates a previously absent marker");player.setShiftKeyDown(false);
        var golem=worker(level,player,p,4);c.accept(Math.abs(golem.getBbHeight()-.95)<1e-6&&Math.abs(golem.getBbWidth()-.4)<1e-6&&golem.getAttributeValue(net.minecraft.world.entity.ai.attributes.Attributes.STEP_HEIGHT)==1,"native worker collision size and full-block step height match original bell line origin");golem.replaceMarkers(List.of(new GolemMarker(level.dimension(),p.west(2),Direction.WEST,-1)));
        c.accept(bell.getItem().interactLivingEntity(bell,player,golem,InteractionHand.MAIN_HAND).consumesAction(),"native bell entity click selects the actual worker");c.accept(GolemBellItem.selected(bell,level)==golem&&GolemBellItem.markers(bell).equals(golem.markers()),"selection replaces preselection markers with the worker's existing list");c.accept(GolemBellItem.data(bell).getLong("Home")==p.asLong()&&GolemBellItem.data(bell).getByte("HomeFace")==Direction.UP.get3DDataValue(),"bell synchronizes native entity id, UUID and home face for its overlay");
        player.getAbilities().instabuild=true;bell.getItem().interactLivingEntity(bell.copy(),player,golem,InteractionHand.MAIN_HAND);bell=player.getMainHandItem();c.accept(GolemBellItem.selected(bell,level)==golem,"creative copied-stack interaction writes selection back to actual hand like TC4");player.getAbilities().instabuild=false;
        for(var face:Direction.values()){var pos=p.east(face.get3DDataValue()+2);GolemBellItem.changeMarkers(bell,player,pos,face);c.accept(golem.markers().stream().anyMatch(m->m.pos().equals(pos)&&m.face()==face&&m.color()==-1),"bell retains original marked face "+face);}
        var color=p.north(3);GolemBellItem.changeMarkers(bell,player,color,Direction.SOUTH);for(int i=0;i<16;i++){GolemBellItem.changeMarkers(bell,player,color,Direction.SOUTH);int expected=i;c.accept(golem.markers().stream().anyMatch(m->m.pos().equals(color)&&m.color()==expected),"Ordo bell cycles marker color "+i);}GolemBellItem.changeMarkers(bell,player,color,Direction.SOUTH);c.accept(golem.markers().stream().noneMatch(m->m.pos().equals(color)),"click after color 15 removes the marker");
        GolemBellItem.changeMarkers(bell,player,color,Direction.SOUTH);player.setShiftKeyDown(true);GolemBellItem.changeMarkers(bell,player,color,Direction.SOUTH);c.accept(golem.markers().stream().noneMatch(m->m.pos().equals(color)),"Shift removes an existing colored marker without cycling");player.setShiftKeyDown(false);
        var far=p.east(100);GolemBellItem.changeMarkers(bell,player,far,Direction.UP);c.accept(golem.markers().stream().anyMatch(m->m.pos().equals(far)),"original bell stores out-of-range markers; worker range controls usage");
        GolemBellItem.resetMarkers(player);c.accept(golem.markers().isEmpty()&&GolemBellItem.markers(bell).isEmpty()&&GolemBellItem.selected(bell,level)==golem,"F reset clears both marker lists while retaining selection");
        var second=worker(level,player,p.east(4),-1);bell.getItem().interactLivingEntity(bell,player,second,InteractionHand.MAIN_HAND);GolemBellItem.changeMarkers(bell,player,color,Direction.UP);GolemBellItem.changeMarkers(bell,player,color,Direction.UP);c.accept(second.markers().isEmpty(),"bell without Ordo removes its repeated marker directly");second.discard();GolemBellItem.changeMarkers(bell,player,color,Direction.UP);c.accept(!GolemBellItem.data(bell).hasUUID("Golem")&&GolemBellItem.markers(bell).isEmpty(),"stale selection clears its home and markers after worker removal");
        var water=p.east(6);level.setBlockAndUpdate(water,net.minecraft.world.level.block.Blocks.WATER.defaultBlockState());for(int dy=1;dy<=4;dy++)level.setBlockAndUpdate(water.above(dy),net.minecraft.world.level.block.Blocks.AIR.defaultBlockState());player.moveTo(water.getX()+.5,water.getY()+1,water.getZ()+.5,0,90);player.xo=player.getX();player.yo=player.getY();player.zo=player.getZ();player.xRotO=90;player.yRotO=0;bell.getItem().use(level,player,InteractionHand.MAIN_HAND);c.accept(GolemBellItem.markers(bell).stream().anyMatch(m->m.pos().equals(water)&&m.face()==Direction.UP),"native bell use ray traces a water source and stores its actual surface face");level.removeBlock(water,false);
        var codec=(CompoundTag)bell.save(level.registryAccess());c.accept(ItemStack.matches(bell,ItemStack.parseOptional(level.registryAccess(),codec)),"bell snapshot survives native item codec");
        golem.color(0,5);golem.toggle(1,true);golem.setCustomName(net.minecraft.network.chat.Component.literal("Bell QA"));golem.filters.setItem(0,new ItemStack(Items.EMERALD,5));golem.replaceMarkers(List.of(new GolemMarker(level.dimension(),p,Direction.UP,3)));golem.carried(new ItemStack(Items.DIAMOND,2));bell.getItem().onLeftClickEntity(bell,player,golem);var drops=level.getEntitiesOfClass(ItemEntity.class,new AABB(p).inflate(3));var body=drops.stream().map(ItemEntity::getItem).filter(s->s.getItem() instanceof GolemPlacerItem).findFirst().orElseThrow();var config=GolemBellItem.data(body);c.accept(!golem.isAlive()&&config.getInt("core")==4&&config.getString("deco").equals("H")&&config.getBoolean("advanced")&&body.has(DataComponents.CUSTOM_NAME)&&config.getList("Markers",10).size()==1&&config.getList("Filters",10).size()==1&&!config.contains("Toggles")&&!config.contains("Colors"),"ordinary bell dismantling preserves name, advanced body, core, upgrades, filters and markers");c.accept(drops.stream().anyMatch(e->e.getItem().is(Items.DIAMOND)&&e.getItem().getCount()==2),"bell dismantling drops the carried real stack exactly once");drops.forEach(ItemEntity::discard);
        golem=worker(level,player,p,4);golem.setCustomName(net.minecraft.network.chat.Component.literal("Discard name"));player.setShiftKeyDown(true);bell.getItem().onLeftClickEntity(bell,player,golem);drops=level.getEntitiesOfClass(ItemEntity.class,new AABB(p).inflate(3));body=drops.stream().map(ItemEntity::getItem).filter(s->s.getItem() instanceof GolemPlacerItem).findFirst().orElseThrow();config=GolemBellItem.data(body);c.accept(config.getBoolean("advanced")&&!config.contains("core")&&!config.contains("deco")&&!config.contains("upgrades")&&!body.has(DataComponents.CUSTOM_NAME),"Shift dismantling retains advancement but resets name, core and accessories like TC4");c.accept(drops.stream().anyMatch(e->e.getItem().is(R3Equipment.GOLEM_CORES.get(GolemCoreItem.Kind.GUARD).get())),"Shift dismantling returns installed core as separate item");drops.forEach(ItemEntity::discard);player.setShiftKeyDown(false);
    }
}
